.mp-page {
  height: 100dvh;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: clamp(10px, 1.5vh, 18px);
  padding: clamp(18px, 2.4vw, 36px);
  background: var(--mp-panel);
  color: var(--mp-ink);
  font-family: var(--mp-font-sans);
  font-size: clamp(13px, 1vw, 16px);
}
.mp-page > * { min-width: 0; }
.mp-head { display: grid; gap: 6px; }
.mp-eyebrow { margin: 0; font-size: 12px; font-weight: 600; letter-spacing: .16em; color: var(--mp-faint); text-transform: uppercase; }
.mp-title { margin: 0; font-size: clamp(24px, 2.7vw, 40px); line-height: 1.12; letter-spacing: -0.01em; font-weight: 700; }
.mp-sub { margin: 0; max-width: 64ch; font-size: clamp(13px, 1.05vw, 16px); line-height: 1.6; color: var(--mp-muted); }

.mp-body { min-height: 0; display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(250px, 1fr); gap: clamp(14px, 1.8vw, 26px); }

.mp-stage { min-height: 0; display: grid; grid-template-rows: minmax(0, 1fr) auto auto auto; gap: clamp(8px, 1.2vh, 16px); padding: clamp(14px, 1.7vw, 26px); border: 1px solid var(--mp-border); border-radius: 20px; background: var(--mp-raised); }
.mp-array { min-height: 0; display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: clamp(4px, .5vw, 8px); align-content: center; }
.mp-cell { position: relative; display: grid; align-content: center; justify-items: center; gap: 3px; min-height: clamp(48px, 9vh, 88px); border: 1px solid var(--mp-border); border-radius: 12px; background: var(--mp-panel); transition: background-color 200ms ease, color 200ms ease, border-color 200ms ease, opacity 200ms ease; }
.mp-val { font-family: var(--mp-font-mono); font-size: clamp(15px, 1.5vw, 23px); font-weight: 600; line-height: 1; }
.mp-idx { font-family: var(--mp-font-mono); font-size: 11px; line-height: 1; color: var(--mp-faint); }
.mp-cell[data-mp-state="in-range"] { border-color: var(--mp-border-strong); }
.mp-cell[data-mp-state="excluded"] { opacity: .32; }
.mp-cell[data-mp-role="mid"], .mp-cell[data-mp-role="hit"] { background: var(--mp-invert); color: var(--mp-invert-ink); border-color: var(--mp-invert); opacity: 1; }
.mp-cell[data-mp-role="mid"] .mp-idx, .mp-cell[data-mp-role="hit"] .mp-idx { color: var(--mp-invert-ink); opacity: .72; }

.mp-meter { display: flex; flex-wrap: wrap; gap: 8px; }
.mp-chip { display: inline-flex; align-items: baseline; gap: 6px; padding: 5px 10px; border: 1px solid var(--mp-border); border-radius: 999px; background: var(--mp-panel); font-size: 12px; color: var(--mp-muted); }
.mp-chip b { font-family: var(--mp-font-mono); font-size: 14px; color: var(--mp-ink); }

.mp-status { margin: 0; min-height: 2.6em; font-size: clamp(13px, 1vw, 15px); line-height: 1.6; }

.mp-controls { display: flex; flex-wrap: wrap; gap: 8px; }
.mp-btn { min-height: 40px; padding: 0 16px; border: 1px solid var(--mp-border-strong); border-radius: 12px; background: var(--mp-panel); color: var(--mp-ink); font: inherit; font-size: 14px; cursor: pointer; }
.mp-btn:hover { border-color: var(--mp-ink); }
.mp-btn-primary { background: var(--mp-invert); color: var(--mp-invert-ink); border-color: var(--mp-invert); }
.mp-btn:focus-visible { outline: 2px solid var(--mp-ink); outline-offset: 2px; }

.mp-side { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 12px; }
.mp-note { padding: 12px 14px; border-left: 3px solid var(--mp-border-strong); border-radius: 0 12px 12px 0; background: var(--mp-raised); }
.mp-label { margin: 0 0 4px; font-size: 11px; font-weight: 600; letter-spacing: .14em; color: var(--mp-faint); }
.mp-note-text { margin: 0; font-size: 13px; line-height: 1.65; color: var(--mp-muted); }
.mp-log { margin: 0; padding: 0; list-style: none; display: grid; align-content: start; gap: 6px; overflow: hidden; }
.mp-log li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 4px 10px; padding: 7px 10px; border: 1px solid var(--mp-border); border-radius: 10px; background: var(--mp-panel); font-size: 12px; line-height: 1.5; color: var(--mp-muted); }
.mp-log li b { font-family: var(--mp-font-mono); font-weight: 600; color: var(--mp-ink); }
.mp-log li span { overflow-wrap: anywhere; }
.mp-log li[data-mp-state="hit"] { border-color: var(--mp-border-strong); color: var(--mp-ink); }
.mp-facts { margin: 0; display: grid; gap: 5px; }
.mp-fact { display: grid; grid-template-columns: 4em minmax(0, 1fr); gap: 8px; font-size: 12px; line-height: 1.5; }
.mp-fact dt { margin: 0; color: var(--mp-faint); }
.mp-fact dd { margin: 0; color: var(--mp-muted); overflow-wrap: anywhere; }

.mp-foot { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 10px 16px; font-size: 12px; color: var(--mp-muted); }
.mp-source { margin: 0; }
.mp-hint { margin: 0; color: var(--mp-faint); white-space: nowrap; }

html[data-mp-reduced-motion="true"] .mp-page,
html[data-mp-reduced-motion="true"] .mp-page * { transition: none !important; animation: none !important; }
@media (prefers-reduced-motion: reduce) {
  .mp-page, .mp-page * { transition: none; animation: none; }
}
@media (max-width: 900px) {
  .mp-body { grid-template-columns: minmax(0, 1fr); }
  .mp-side { grid-template-rows: auto auto; }
  .mp-log, .mp-facts { display: none; }
}
@media (max-width: 560px) {
  .mp-array { gap: 2px; }
  .mp-val { font-size: 12px; }
  .mp-idx { display: none; }
  .mp-hint { display: none; }
}

