(function () {
  var VALUES = [3, 7, 11, 18, 23, 29, 34, 41, 52, 60];
  var ROUNDS = [
    { mid: 4, left: 5, right: 9, note: '23 < 29，排除左半' },
    { mid: 7, left: 5, right: 6, note: '41 > 29，排除右半' },
    { mid: 5, left: 5, right: 6, note: '29 = 29，命中下标 5', hit: true }
  ];
  var root = document.querySelector('.mp-page');
  if (!root) { return; }
  var cells = root.querySelectorAll('[data-mp-index]');
  var log = root.querySelector('[data-mp-role="log"]');
  var statusEl = root.querySelector('[data-mp-role="status"]');
  var countEl = root.querySelector('[data-mp-role="count"]');
  var widthEl = root.querySelector('[data-mp-role="width"]');
  var stepBtn = root.querySelector('[data-mp-action="step"]');
  var solveBtn = root.querySelector('[data-mp-action="solve"]');
  var resetBtn = root.querySelector('[data-mp-action="reset"]');
  var applied = 0;

  function range() {
    if (applied === 0) { return { left: 0, right: VALUES.length - 1 }; }
    var r = ROUNDS[applied - 1];
    return { left: r.left, right: r.right };
  }

  function nextMid(left, right) {
    return left + Math.floor((right - left) / 2);
  }

  function render() {
    var r = range();
    var mid;
    var state;
    if (applied === 0) {
      mid = nextMid(r.left, r.right);
      state = 'idle';
    } else if (applied < ROUNDS.length) {
      mid = nextMid(r.left, r.right);
      state = 'stepped';
    } else {
      mid = ROUNDS[ROUNDS.length - 1].mid;
      state = 'hit';
    }
    root.dataset.mpState = state;

    for (var i = 0; i < cells.length; i += 1) {
      var cell = cells[i];
      var idx = Number(cell.getAttribute('data-mp-index'));
      var excluded = idx < r.left || idx > r.right;
      cell.setAttribute('data-mp-state', excluded ? 'excluded' : 'in-range');
      if (idx === mid) {
        cell.setAttribute('data-mp-role', state === 'hit' ? 'hit' : 'mid');
      } else {
        cell.removeAttribute('data-mp-role');
      }
    }

    countEl.textContent = String(applied);
    widthEl.textContent = String(r.right - r.left + 1);

    if (applied === 0) {
      statusEl.textContent = '区间 [' + r.left + ', ' + r.right + ']，mid = ' + mid + '，准备比较 a[' + mid + '] = ' + VALUES[mid] + '。';
    } else if (state === 'hit') {
      statusEl.textContent = '第 ' + applied + ' 轮：a[5] = 29，命中，返回下标 5。区间已缩到 1 个元素。';
    } else {
      var last = ROUNDS[applied - 1];
      statusEl.textContent = '第 ' + applied + ' 轮：a[' + last.mid + '] = ' + VALUES[last.mid] + '，' + last.note + '，新区间 [' + r.left + ', ' + r.right + ']。';
    }

    log.textContent = '';
    for (var k = 0; k < applied; k += 1) {
      var item = document.createElement('li');
      var head = document.createElement('b');
      var text = document.createElement('span');
      var row = ROUNDS[k];
      var from = k === 0 ? 0 : ROUNDS[k - 1].left;
      var to = k === 0 ? VALUES.length - 1 : ROUNDS[k - 1].right;
      head.textContent = '第 ' + (k + 1) + ' 轮';
      text.textContent = '[' + from + ', ' + to + '] mid ' + row.mid + ' · ' + row.note;
      if (row.hit) { item.setAttribute('data-mp-state', 'hit'); }
      item.appendChild(head);
      item.appendChild(text);
      log.appendChild(item);
    }
  }

  function emit() {
    window.MockFinal.emit('interaction', { id: 'bisect-demo', applied: applied, state: root.getAttribute('data-mp-state') });
  }

  if (stepBtn) {
    stepBtn.addEventListener('click', function () {
      if (applied < ROUNDS.length) {
        applied += 1;
        render();
        emit();
      }
    });
  }
  if (solveBtn) {
    solveBtn.addEventListener('click', function () {
      if (applied < ROUNDS.length) {
        applied = ROUNDS.length;
        render();
        emit();
      }
    });
  }
  if (resetBtn) {
    resetBtn.addEventListener('click', function () {
      applied = 0;
      render();
      emit();
    });
  }

  if (typeof window.MockFinal.onHostMessage === 'function') {
    window.MockFinal.onHostMessage(function (msg) {
      if (msg && msg.type === 'theme') { render(); }
    });
  }

  render();
  window.MockFinal.ready({ title: '二分查找：每次排除一半' });
})();
